    csv_data = """name,value
A,10
B,20
C,30"""
    assert sum_column(csv_data, "value") == 60
    try:
        sum_column(csv_data, "unknown")
    except KeyError as e:
        assert str(e) == "Unknown column: unknown"
    else:
        assert False, "KeyError not raised for unknown column"

module.exports = function debounce(fn, ms) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => fn.apply(this, args), ms);
  };
};

const debounce = require('./t10_debounce.js');
const assert = require('assert');

function testDebounce() {
  let callCount = 0;
  const debounced = debounce(() => {
    callCount++;
  }, 100);

  debounced();
  debounced();
  debounced();

  setTimeout(() => {
    assert.strictEqual(callCount, 1);
    console.log('Test passed!');
  }, 200);
}

testDebounce();

